// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetAttachmentFile Download the original image
	// (GET /api/v1/attachments/{id}/file)
	GetAttachmentFile(ctx context.Context, request GetAttachmentFileRequestObject) (GetAttachmentFileResponseObject, error)
	// GetAttachmentThumbnail Download the JPEG thumbnail
	// (GET /api/v1/attachments/{id}/thumbnail)
	GetAttachmentThumbnail(ctx context.Context, request GetAttachmentThumbnailRequestObject) (GetAttachmentThumbnailResponseObject, error)
	// CreateFolder Create a folder
	// (POST /api/v1/folders)
	CreateFolder(ctx context.Context, request CreateFolderRequestObject) (CreateFolderResponseObject, error)
	// ReorderFolders Reorder the child folders of a parent
	// (PUT /api/v1/folders/order)
	ReorderFolders(ctx context.Context, request ReorderFoldersRequestObject) (ReorderFoldersResponseObject, error)
	// DeleteFolder Move a folder and its subtree to the trash
	// (DELETE /api/v1/folders/{id})
	DeleteFolder(ctx context.Context, request DeleteFolderRequestObject) (DeleteFolderResponseObject, error)
	// GetFolder Get a folder
	// (GET /api/v1/folders/{id})
	GetFolder(ctx context.Context, request GetFolderRequestObject) (GetFolderResponseObject, error)
	// UpdateFolder Rename a folder
	// (PATCH /api/v1/folders/{id})
	UpdateFolder(ctx context.Context, request UpdateFolderRequestObject) (UpdateFolderResponseObject, error)
	// MoveFolder Move a folder under another parent
	// (POST /api/v1/folders/{id}/move)
	MoveFolder(ctx context.Context, request MoveFolderRequestObject) (MoveFolderResponseObject, error)
	// DeleteItem Move an item to the trash
	// (DELETE /api/v1/items/{id})
	DeleteItem(ctx context.Context, request DeleteItemRequestObject) (DeleteItemResponseObject, error)
	// GetItem Get an item
	// (GET /api/v1/items/{id})
	GetItem(ctx context.Context, request GetItemRequestObject) (GetItemResponseObject, error)
	// UpdateItem Update an item
	// (PATCH /api/v1/items/{id})
	UpdateItem(ctx context.Context, request UpdateItemRequestObject) (UpdateItemResponseObject, error)
	// GetItemContent Get the current Markdown content
	// (GET /api/v1/items/{id}/content)
	GetItemContent(ctx context.Context, request GetItemContentRequestObject) (GetItemContentResponseObject, error)
	// UpdateItemContent Save the Markdown content
	// (PUT /api/v1/items/{id}/content)
	UpdateItemContent(ctx context.Context, request UpdateItemContentRequestObject) (UpdateItemContentResponseObject, error)
	// RestoreContentVersion Restore an older content version
	// (POST /api/v1/items/{id}/content/restore)
	RestoreContentVersion(ctx context.Context, request RestoreContentVersionRequestObject) (RestoreContentVersionResponseObject, error)
	// ListContentVersions List the saved content versions
	// (GET /api/v1/items/{id}/content/versions)
	ListContentVersions(ctx context.Context, request ListContentVersionsRequestObject) (ListContentVersionsResponseObject, error)
	// GetContentVersion Get one content version (for preview)
	// (GET /api/v1/items/{id}/content/versions/{version})
	GetContentVersion(ctx context.Context, request GetContentVersionRequestObject) (GetContentVersionResponseObject, error)
	// DeleteItemImage Remove the item image
	// (DELETE /api/v1/items/{id}/image)
	DeleteItemImage(ctx context.Context, request DeleteItemImageRequestObject) (DeleteItemImageResponseObject, error)
	// SetItemImage Set the item image (upload or URL)
	// (PUT /api/v1/items/{id}/image)
	SetItemImage(ctx context.Context, request SetItemImageRequestObject) (SetItemImageResponseObject, error)
	// MoveItem Move an item to another list
	// (POST /api/v1/items/{id}/move)
	MoveItem(ctx context.Context, request MoveItemRequestObject) (MoveItemResponseObject, error)
	// CreateList Create a list
	// (POST /api/v1/lists)
	CreateList(ctx context.Context, request CreateListRequestObject) (CreateListResponseObject, error)
	// ReorderLists Reorder the child lists of a folder
	// (PUT /api/v1/lists/order)
	ReorderLists(ctx context.Context, request ReorderListsRequestObject) (ReorderListsResponseObject, error)
	// DeleteList Move a list and its items to the trash
	// (DELETE /api/v1/lists/{id})
	DeleteList(ctx context.Context, request DeleteListRequestObject) (DeleteListResponseObject, error)
	// GetList Get a list
	// (GET /api/v1/lists/{id})
	GetList(ctx context.Context, request GetListRequestObject) (GetListResponseObject, error)
	// UpdateList Update a list
	// (PATCH /api/v1/lists/{id})
	UpdateList(ctx context.Context, request UpdateListRequestObject) (UpdateListResponseObject, error)
	// ListItems List the items of a list
	// (GET /api/v1/lists/{id}/items)
	ListItems(ctx context.Context, request ListItemsRequestObject) (ListItemsResponseObject, error)
	// CreateItem Create an item
	// (POST /api/v1/lists/{id}/items)
	CreateItem(ctx context.Context, request CreateItemRequestObject) (CreateItemResponseObject, error)
	// ReorderListItems Reorder the items of a list
	// (PUT /api/v1/lists/{id}/items/order)
	ReorderListItems(ctx context.Context, request ReorderListItemsRequestObject) (ReorderListItemsResponseObject, error)
	// MoveList Move a list to another folder
	// (POST /api/v1/lists/{id}/move)
	MoveList(ctx context.Context, request MoveListRequestObject) (MoveListResponseObject, error)
	// ListRecentItems List recently updated items
	// (GET /api/v1/recent-items)
	ListRecentItems(ctx context.Context, request ListRecentItemsRequestObject) (ListRecentItemsResponseObject, error)
	// SearchItems Search items by title
	// (GET /api/v1/search)
	SearchItems(ctx context.Context, request SearchItemsRequestObject) (SearchItemsResponseObject, error)
	// GetSettings Get workspace settings
	// (GET /api/v1/settings)
	GetSettings(ctx context.Context, request GetSettingsRequestObject) (GetSettingsResponseObject, error)
	// UpdateSettings Update workspace settings
	// (PATCH /api/v1/settings)
	UpdateSettings(ctx context.Context, request UpdateSettingsRequestObject) (UpdateSettingsResponseObject, error)
	// ListTrash List trash entries
	// (GET /api/v1/trash)
	ListTrash(ctx context.Context, request ListTrashRequestObject) (ListTrashResponseObject, error)
	// PurgeTrashBatch Purge a trash batch permanently
	// (DELETE /api/v1/trash/{batch_id})
	PurgeTrashBatch(ctx context.Context, request PurgeTrashBatchRequestObject) (PurgeTrashBatchResponseObject, error)
	// RestoreTrashBatch Restore a trash batch
	// (POST /api/v1/trash/{batch_id}/restore)
	RestoreTrashBatch(ctx context.Context, request RestoreTrashBatchRequestObject) (RestoreTrashBatchResponseObject, error)
	// GetTree Get the sidebar tree
	// (GET /api/v1/tree)
	GetTree(ctx context.Context, request GetTreeRequestObject) (GetTreeResponseObject, error)
	// CheckHealth Liveness probe
	// (GET /healthz)
	CheckHealth(ctx context.Context, request CheckHealthRequestObject) (CheckHealthResponseObject, error)
	// CheckReadiness Readiness probe
	// (GET /readyz)
	CheckReadiness(ctx context.Context, request CheckReadinessRequestObject) (CheckReadinessResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

